<?php
use EIPSI\StudyEngine\Longitudinal as L;use EIPSI\StudyEngine\Persistence as P;use EIPSI\StudyEngine\Runtime as R;use EIPSI\AssessmentEditor\Runtime as N;use EIPSI\AssessmentEditor\Definition as D;use EIPSI\StudyEngine\Contracts\Canonical;
function c3l_version($prefix,$pages=2,$samePage=false){
 $base=json_decode(file_get_contents(dirname(__DIR__).'/assessment-editor/functional-fixture.json'),true);$q=$base['elements'][0];$break=$base['elements'][3];$base['id']='AE_SEC3_'.bin2hex(random_bytes(8));$base['elements']=array();$base['flow']['pages']=array();$base['flow']['allow_back']=true;
 for($i=0;$i<$pages;$i++){if($i&&!$samePage){$b=$break;$b['id']=$prefix.'_PAGE_'.$i;$base['elements'][]=$b;}$item=$q;$item['id']=$prefix.'_Q'.$i;$item['response_key']=$prefix.'_R'.$i;$item['properties']['variable_name']=$prefix.'_var'.$i;$item['properties']['required']=true;$base['elements'][]=$item;}
 $base=D::validate($base);$o=c3l_owner();$o->store->install();$json=D::json($base);$v=array('id'=>'NV_SEC3_'.bin2hex(random_bytes(8)),'assessment_id'=>$base['id'],'author_revision'=>1,'definition_json'=>$json,'definition_hash'=>hash('sha256',$json),'state'=>'PUBLISHED','actor_id'=>1,'created_at'=>strtotime($GLOBALS['pf_now']));$o->store->transaction(fn()=>$o->store->insert('versions',$v));return array('row'=>$v,'definition'=>$base);
}
function c3l_logic($kind=null,$future=false,$samePage=false){
 $source=c3l_version('SOURCE',2,$samePage);$target=c3l_version('TARGET');$d=pe_definition();$d['nodes']=array_values(array_filter($d['nodes'],static fn($n)=>$n['kind']==='BLOCK'));$sourceNode=null;
 foreach($d['nodes']as&$n){if($n['parent_id']===$d['id'])$n['children_strategy']='PARALLEL_AVAILABLE';if($n['completion_boundary']==='ASSESSMENT'){$n['metadata']=array('native_version_id'=>$source['row']['id'],'native_definition_hash'=>$source['row']['definition_hash'],'native_questions'=>c3l_catalog($source['definition']));$sourceNode=$n;}}unset($n);
 $to=$sourceNode;$to['id']='E_SEC2_TARGET';$to['logical_id']=$to['id'];$to['position']++;$to['metadata']=array('native_version_id'=>$target['row']['id'],'native_definition_hash'=>$target['row']['definition_hash'],'native_questions'=>c3l_catalog($target['definition']));if($future)$to['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'ELAPSED','seconds'=>3600));$d['nodes'][]=$to;
 foreach(array($sourceNode,$to)as$n){$json=Canonical::json(array('label'=>'Native','html'=>''));$id='C_'.$n['id'];$d['nodes'][]=array('kind'=>'CONTENT','id'=>$id,'version_id'=>$d['id'],'parent_id'=>$n['id'],'position'=>0,'type'=>'TEXT','content'=>array('content_id'=>$id,'version'=>1,'snapshot'=>$json,'sha256'=>hash('sha256',$json)),'durable_reference'=>null);}
 if($kind!==null)$d['protocol_metadata']['trajectory_conditions']=array(array('id'=>'SEC2_LOGIC','label'=>'Condición de prueba','source'=>array('assessment_id'=>$sourceNode['id'],'question_id'=>'SOURCE_Q0'),'event'=>'ANSWER','priority'=>1,'predicate'=>array('op'=>'EQ','reference'=>array('kind'=>'ANSWER','assessment_id'=>$sourceNode['id'],'question_id'=>'SOURCE_Q0'),'value'=>'go'),'actions'=>array(array('type'=>$kind,'target_id'=>$kind==='GO_QUESTION'?$sourceNode['id']:$to['id'],'question_id'=>$kind==='GO_QUESTION'?'SOURCE_Q1':'TARGET_Q1'))));
 $p=pe_publish('simple',false,L\Configuration::apply($d,array('verification_policy'=>'ALLOW_UNVERIFIED')));$GLOBALS['c3l_studies'][]=$d['study']['logical_id'];$f=pf_enroll($p);$id=c3l_native($p,$f)['execution_id'];return array($p,$f,$id,$source,$target);
}
function c3l_catalog($d){$out=array();$page=0;foreach($d['elements']as$e){if($e['type']==='page_break'){$page++;continue;}$out[]=array('id'=>$e['id'],'label'=>$e['id'],'response_key'=>$e['response_key'],'value_type'=>'STRING','options'=>array(),'page'=>$page,'randomization_id'=>null);}return$out;}
